mapper.select:
SELECT o.id AS outstockId, o.out_no AS outNo, o.customer_id AS customerId, NULL AS customerName, o.out_date AS outDate, COALESCE(d.sum_amount, o.total_amount) AS amount FROM sal_outstock o LEFT JOIN (SELECT out_id, SUM(amount) AS sum_amount FROM sal_outstock_detail WHERE deleted = 0 GROUP BY out_id) d ON d.out_id = o.id WHERE o.deleted = 0 AND o.status = 10
AND o.customer_id = #{customerId}
AND NOT EXISTS (SELECT 1 FROM inv_sales_invoice i WHERE i.deleted = 0 AND i.biz_type = 'SAL_OUTSTOCK' AND i.biz_id = o.id AND i.red_flag = 0 AND i.status IN (0, 10)) ORDER BY o.out_date DESC, o.id DESC

SELECT p.id AS instockId, p.instock_no AS instockNo, p.supplier_id AS supplierId, NULL AS supplierName, p.instock_date AS instockDate, p.total_amount AS amount FROM pur_instock p WHERE p.deleted = 0 AND p.status = 10
AND p.supplier_id = #{supplierId}
AND NOT EXISTS (SELECT 1 FROM inv_purchase_invoice i WHERE i.deleted = 0 AND i.biz_type = 'PUR_INSTOCK' AND i.biz_id = p.id AND i.red_flag = 0 AND i.status IN (0, 10)) ORDER BY p.instock_date DESC, p.id DESC
